                function fmt(val) {
                  if (val === null || val === undefined || isNaN(val)) return '$0.00';
                  return '$' + Number(val).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
                }

                function fmtPct(val) {
                  if (val === null || val === undefined || isNaN(val)) return '0.00%';
                  return Number(val).toFixed(2) + '%';
                }

                function showToast(message, isError = false) {
                  const toast = document.getElementById('toast');
                  const toastMsg = document.getElementById('toastMessage');
                  toastMsg.textContent = message;
                  toast.className = isError ? 'active error' : 'active';
                  setTimeout(() => toast.className = '', 3000);
                }

                async function decodeVIN(vin, card) {
                  if (!vin || vin.length !== 17) {
                    showToast('VIN must be 17 characters', true);
                    return;
                  }

                  card.querySelector('.field-loading').textContent = '⏳ Decoding VIN...';
                  card.querySelector('.field-error').textContent = '';

                  try {
                    // Step 1: MarketCheck decode
                    const mcResp = await fetch(`https://mc-api.marketcheck.com/v2/decode/car/vin/${vin}?api_key=${MARKETCHECK_API_KEY}`);
                    const mcData = await mcResp.json();

                    if (mcData.year) card.querySelector('.year').value = mcData.year;
                    if (mcData.make) card.querySelector('.make').value = mcData.make;
                    if (mcData.model) card.querySelector('.model').value = mcData.model;
                    if (mcData.trim) card.querySelector('.trim').value = mcData.trim;
                    if (mcData.exterior_color) card.querySelector('.color').value = mcData.exterior_color;

                    // Step 2: NHTSA decode for additional specs
                    const nhtsaResp = await fetch(`${NHTSA_API_BASE}/DecodeVin/${vin}?format=json`);
                    const nhtsaData = await nhtsaResp.json();

                    if (nhtsaData.Results) {
                      const fuelType = nhtsaData.Results.find(r => r.Variable === 'Fuel Type - Primary')?.Value || 'Gas';
                      setFuelType(card, fuelType);
                    }

                    // Step 3: Pull EPA data from embedded script
                    const year = card.querySelector('.year').value;
                    const make = card.querySelector('.make').value;
                    const model = card.querySelector('.model').value;
                    const trim = card.querySelector('.trim').value;

                    if (EPA_DATA[year] && EPA_DATA[year][make] && EPA_DATA[year][make][model] && EPA_DATA[year][make][model][trim]) {
                      const epaInfo = EPA_DATA[year][make][model][trim];

                      if (epaInfo.cityMPGe) {
                        card.querySelector('.mpgeCity').value = epaInfo.cityMPGe;
                        card.querySelector('.mpgeHwy').value = epaInfo.hwyMPGe;
                        card.querySelector('.mpgeCombined').value = epaInfo.combMPGe;
                        card.querySelector('.batterySize').value = epaInfo.batteryKWh;
                        card.querySelector('.rangeElectric').value = epaInfo.rangeElectric;
                      } else if (epaInfo.cityMPG) {
                        card.querySelector('.epaCityMpg').value = epaInfo.cityMPG;
                        card.querySelector('.epaHwyMpg').value = epaInfo.hwyMPG;
                        card.querySelector('.epaCombinedMpg').value = epaInfo.combMPG;
                        card.querySelector('.fuelTankSize').value = epaInfo.tankGal || 0;
                      }
                    }

                    card.querySelector('.field-loading').textContent = '✅ Decoded';
                    showToast('VIN decoded successfully');
                  } catch (err) {
                    card.querySelector('.field-error').textContent = '❌ Decode failed';
                    card.querySelector('.field-loading').textContent = '';
                    showToast('Failed to decode VIN', true);
                  }
                }

                async function lookupZip(zip, card) {
                  if (!zip || zip.length !== 5) return;

                  try {
                    const resp = await fetch(`http://api.positionstack.com/v1/forward?access_key=${POSITIONSTACK_API_KEY}&query=${zip}`);
                    const data = await resp.json();

                    if (data.data && data.data.length > 0) {
                      const loc = data.data[0];
                      card.querySelector('.city').value = loc.locality || '';
                      card.querySelector('.state').value = loc.region_code || '';
                      card.querySelector('.county').value = loc.county || '';
                    }
                  } catch (err) {
                    console.error('Zip lookup failed:', err);
                  }
                }

                function setFuelType(card, type) {
                  const fuelLower = type.toLowerCase();
                  let detectedType = 'gas';

                  if (fuelLower.includes('electric') || fuelLower.includes('ev')) {
                    detectedType = 'ev';
                  } else if (fuelLower.includes('plug-in') || fuelLower.includes('phev')) {
                    detectedType = 'phev';
                  }

                  card.querySelector('.fuelType').value = detectedType;
                  card.querySelector('.fuelTypeDisplay').value = detectedType.toUpperCase();

               // Show/hide fields
                  card.querySelectorAll('.gas-field').forEach(el => el.classList.toggle('hidden', detectedType !== 'gas'));
                  card.querySelectorAll('.ev-field').forEach(el => el.classList.toggle('hidden', detectedType !== 'ev'));
                  card.querySelectorAll('.phev-field').forEach(el => el.classList.toggle('hidden', detectedType !== 'phev'));
                  card.querySelectorAll('[data-ev-only]').forEach(el => el.parentElement.classList.toggle('ev-field-hidden', detectedType === 'gas'));
                }

                function calculateFuelCosts(card) {
                  const fuelType = card.querySelector('.fuelType').value;
                  const annualMiles = parseFloat(card.querySelector('.annualMileage').value) || 12000;

                  if (fuelType === 'gas') {
                    const combMPG = parseFloat(card.querySelector('.epaCombinedMpg').value) || 25;
                    const gasPrice = parseFloat(card.querySelector('.avgGasPrice').value) || 2.65;
                    const tankSize = parseFloat(card.querySelector('.fuelTankSize').value) || 0;
                    const rangeGas = combMPG * tankSize;

                    card.querySelector('.rangeGas').value = rangeGas.toFixed(0);

                    const annualCost = (annualMiles / combMPG) * gasPrice;
                    card.querySelector('.annualFuelCost').value = annualCost.toFixed(2);
                  } else if (fuelType === 'ev') {
                    const combMPGe = parseFloat(card.querySelector('.mpgeCombined').value) || 100;
                    const l2Cost = parseFloat(card.querySelector('.l2electricityCost').value) || 0.1855;
                    const l3Cost = parseFloat(card.querySelector('.l3electricityCost').value) || 0.4555;

                    const kWhPer100Mi = 33.7 / combMPGe * 100;
                    const annualKWh = (annualMiles / 100) * kWhPer100Mi;

                    card.querySelector('.annualChargingCostL2').value = (annualKWh * l2Cost).toFixed(2);
                    card.querySelector('.annualChargingCostL3').value = (annualKWh * l3Cost).toFixed(2);
                  } else if (fuelType === 'phev') {
                    const electricPct = parseFloat(card.querySelector('.phevElectricPct').value) || 60;
                    const combMPGe = parseFloat(card.querySelector('.mpgeCombined').value) || 80;
                    const combMPG = parseFloat(card.querySelector('.epaCombinedMpg').value) || 35;
                    const gasPrice = parseFloat(card.querySelector('.avgGasPrice').value) || 2.65;
                    const l2Cost = parseFloat(card.querySelector('.l2electricityCost').value) || 0.1855;

                    const electricMiles = annualMiles * (electricPct / 100);
                    const gasMiles = annualMiles - electricMiles;

                    const kWhPer100Mi = 33.7 / combMPGe * 100;
                    const electricKWh = (electricMiles / 100) * kWhPer100Mi;

                    card.querySelector('.annualFuelCostPHEV').value = ((gasMiles / combMPG) * gasPrice).toFixed(2);
                    card.querySelector('.annualChargingCostPHEV').value = (electricKWh * l2Cost).toFixed(2);
                  }
                }

                function addVehicle() {
                  vehicleCounter++;
                  const template = document.getElementById('vehicleCardTemplate');
                  const clone = template.content.cloneNode(true);
                  const card = clone.querySelector('.vehicle-card');

                  card.dataset.vehicleId = vehicleCounter;
                  card.querySelector('.v-num').textContent = vehicleCounter;

                  const scenarioSelect = card.querySelector('.scenarioSelect');
                  SCENARIOS.forEach(s => {
                    const opt = document.createElement('option');
                    opt.value = s.id;
                    opt.textContent = s.name;
                    scenarioSelect.appendChild(opt);
                  });

                  card.querySelector('.vin').addEventListener('blur', (e) => decodeVIN(e.target.value, card));
                  card.querySelector('.zip').addEventListener('blur', (e) => lookupZip(e.target.value, card));
                  card.querySelector('.vehicleCondition').addEventListener('change', (e) => {
                    const isCPOUsed = e.target.value !== 'new';
                    card.querySelectorAll('.cpo-used-fields').forEach(el => el.classList.toggle('hidden', !isCPOUsed));
                  });

                  card.querySelector('.msdActive').addEventListener('change', (e) => {
                    card.querySelectorAll('.msd-field').forEach(el => el.classList.toggle('hidden', !e.target.checked));
                  });

                  card.querySelector('.tradeScenario').addEventListener('change', (e) => {
                    card.querySelectorAll('.check-back-field').forEach(el => el.classList.toggle('hidden', e.target.value !== 'checkback'));
                  });

                  card.querySelector('.dealType').addEventListener('change', (e) => {
                    const isBalloon = e.target.value === 'balloon';
                    card.querySelectorAll('.balloon-fields').forEach(el => el.classList.toggle('hidden', !isBalloon));
                  });

                  ['epaCombinedMpg', 'avgGasPrice', 'annualMileage', 'mpgeCombined', 'l2electricityCost', 'l3electricityCost'].forEach(cls => {
                    const input = card.querySelector(`.${cls}`);
                    if (input) input.addEventListener('input', () => calculateFuelCosts(card));
                  });

                  card.querySelector('.scenarioSelect').addEventListener('change', (e) => {
                    const scenario = SCENARIOS.find(s => s.id === e.target.value);
                    if (scenario) {
                      card.querySelector('.scenario-details').classList.remove('hidden');
                      const infoDiv = card.querySelector('.scenario-info');
                      infoDiv.innerHTML = `<p><strong>${scenario.name}</strong></p><p>${scenario.description}</p>`;
                      card.dataset.selectedScenario = JSON.stringify(scenario.params);
                    } else {
                      card.querySelector('.scenario-details').classList.add('hidden');
                    }
                  });

                  document.getElementById('vehiclesContainer').appendChild(clone);
                  vehicles.push({ id: vehicleCounter, card });
                  updateVehicleCount();
                }

                function updateVehicleCount() {
                  document.getElementById('vehicleCount').textContent = vehicles.length;
                }

                function duplicateVehicle(btn) {
                                showToast('Vehicle duplicated');
                }

                function clearVehicle(btn) {
                  const card = btn.closest('.vehicle-card');
                  card.querySelectorAll('input[type="number"], input[type="text"]').forEach(inp => {
                    if (!inp.readOnly) inp.value = '';
                  });
                  showToast('Vehicle cleared');
                }

                function removeVehicle(btn) {
                  const card = btn.closest('.vehicle-card');
                  const id = parseInt(card.dataset.vehicleId);
                  const idx = vehicles.findIndex(v => v.id === id);
                  if (idx > -1) vehicles.splice(idx, 1);
                  card.remove();
                  updateVehicleCount();
                  showToast('Vehicle removed');
                }

                function switchVehicleTab(btn, tab) {
                  const card = btn.closest('.vehicle-card');
                  card.querySelectorAll('.vehicle-tab-btn').forEach(b => b.classList.remove('active'));
                  card.querySelectorAll('.vehicle-tab-content').forEach(c => c.classList.remove('active'));

                  btn.classList.add('active');
                  card.querySelector(`.vehicle-tab-content[data-tab="${tab}"]`).classList.add('active');
                }

                function applyScenario(btn) {
                  const card = btn.closest('.vehicle-card');
                  const params = JSON.parse(card.dataset.selectedScenario || '{}');

                  Object.keys(params).forEach(key => {
                    const input = card.querySelector(`.${key}`);
                    if (input) {
                      if (input.type === 'checkbox') {
                        input.checked = params[key];
                        input.dispatchEvent(new Event('change'));
                      } else {
                        input.value = params[key];
                      }
                    }
                  });

                  showToast('Scenario applied');
                  calculateVehicle(card);
                }

