/**
 * amortization_engine.js
 * Amortization and payment schedule generation
 */
function generateAmortizationSchedule(principal, apr, termMonths, firstPaymentDate = new Date()) {
    const schedule = [];
    const monthlyRate = apr / 100 / 12;
    const monthlyPayment = principal * (monthlyRate * Math.pow(1 + monthlyRate, termMonths)) / 
                          (Math.pow(1 + monthlyRate, termMonths) - 1);
    
    let balance = principal;
    let currentDate = new Date(firstPaymentDate);
    
    for (let month = 1; month <= termMonths; month++) {
        const interestPayment = balance * monthlyRate;
        const principalPayment = monthlyPayment - interestPayment;
        balance -= principalPayment;
        
        schedule.push({
            month,
            date: new Date(currentDate),
            payment: monthlyPayment,
            principal: principalPayment,
            interest: interestPayment,
            balance: Math.max(0, balance),
            totalInterest: schedule.reduce((sum, p) => sum + p.interest, interestPayment)
        });
        
        // Advance to next month
        currentDate.setMonth(currentDate.getMonth() + 1);
    }
    
    return schedule;
}
function generateLeaseSchedule(capCost, residualValue, moneyFactor, termMonths, firstPaymentDate = new Date()) {
    const schedule = [];
    const depreciation = capCost - residualValue;
    const monthlyDepreciation = depreciation / termMonths;
    const monthlyRentCharge = (capCost + residualValue) * moneyFactor;
    const monthlyPayment = monthlyDepreciation + monthlyRentCharge;
    
    let currentDate = new Date(firstPaymentDate);
    let accumulatedDep = 0;
    
    for (let month = 1; month <= termMonths; month++) {
        accumulatedDep += monthlyDepreciation;
        
        schedule.push({
            month,
            date: new Date(currentDate),
            payment: monthlyPayment,
            depreciation: monthlyDepreciation,
            rentCharge: monthlyRentCharge,
            accumulatedDepreciation: accumulatedDep,
            bookValue: capCost - accumulatedDep,
            residualValue: residualValue
        });
        
        currentDate.setMonth(currentDate.getMonth() + 1);
    }
    
    return schedule;
}

function generateBalloonSchedule(principal, balloonAmount, apr, termMonths, firstPaymentDate = new Date()) {
    const schedule = [];
    const monthlyRate = apr / 100 / 12;
    
    // Calculate payment for principal minus balloon
    const financedAmount = principal - balloonAmount;
    const monthlyPayment = financedAmount * (monthlyRate * Math.pow(1 + monthlyRate, termMonths)) / 
                          (Math.pow(1 + monthlyRate, termMonths) - 1);
    
    let balance = principal;
    let currentDate = new Date(firstPaymentDate);
    
    for (let month = 1; month <= termMonths; month++) {
        const interestPayment = balance * monthlyRate;
        const principalPayment = monthlyPayment - interestPayment;
        balance -= principalPayment;
        
        const isFinalPayment = month === termMonths;
        const actualPayment = isFinalPayment ? monthlyPayment + balloonAmount : monthlyPayment;
        
        schedule.push({
            month,
            date: new Date(currentDate),
            payment: actualPayment,
            regularPayment: monthlyPayment,
            balloonPayment: isFinalPayment ? balloonAmount : 0,
            principal: principalPayment,
            interest: interestPayment,
            balance: Math.max(0, balance),
            isFinalPayment
        });
        
        currentDate.setMonth(currentDate.getMonth() + 1);
    }
    
    return schedule;
}

