function calculateFinance(card) {
                                                var msrp = parseFloat(card.querySelector('.msrp')?.value || 0);
                                                var listingPrice = parseFloat(card.querySelector('.listingPrice')?.value || msrp);
                                                var apr = parseFloat(card.querySelector('.apr')?.value || 0) / 100;
                                                var term = parseInt(card.querySelector('.financeTerm')?.value || 60);
                                                var downPayment = parseFloat(card.querySelector('.downPayment')?.value || 0);
                                                var incentives = parseFloat(card.querySelector('.financeIncentives')?.value || 0);
                                                var balloonAmount = parseFloat(card.querySelector('.balloonAmount')?.value || 0);
                                                var docFee = parseFloat(card.querySelector('.docFee')?.value || 0);
                                                var regFee = parseFloat(card.querySelector('.regFee')?.value || 0);
                                                var titleFee = parseFloat(card.querySelector('.titleFee')?.value || 0);
                                                var plateFee = parseFloat(card.querySelector('.plateFee')?.value || 0);
                                                var otherFees = parseFloat(card.querySelector('.otherFees')?.value || 0);
                                                var tradeAllowance = parseFloat(card.querySelector('.tradeAllowance')?.value || 0);
                                                var payoffAmount = parseFloat(card.querySelector('.payoffAmount')?.value || 0);

                                                if (!listingPrice || !apr || !term) {
                                                  showToast('Missing required finance fields');
                                                  return false;
                                                }

                                                var fees = docFee + regFee + titleFee + plateFee + otherFees;
                                                var loanAmount = listingPrice - downPayment - incentives - tradeAllowance + payoffAmount + fees - balloonAmount;

                                                var monthlyRate = apr / 12;
                                                var monthlyPayment = loanAmount * (monthlyRate * Math.pow(1 + monthlyRate, term)) / (Math.pow(1 + monthlyRate, term) - 1);

                                                var totalPayments = monthlyPayment * term + balloonAmount;
                                                var totalInterest = totalPayments - loanAmount;
                                                var totalCost = totalPayments + downPayment;

                                                var annualMileage = parseFloat(card.querySelector('.annualMileage')?.value || 18000);
                                                var totalMiles = (annualMileage / 12) * term;
                                                var costPerMile = totalCost / totalMiles;

                                                // Populate breakdown
                                                setFieldValue(card, '[data-field="finLoanAmount"]', `$${loanAmount.toFixed(0)}`);
                                                setFieldValue(card, '[data-field="finMonthlyPayment"]', `$${monthlyPayment.toFixed(2)}`);
                                                setFieldValue(card, '[data-field="finTotalInterest"]', `$${totalInterest.toFixed(0)}`);
                                                setFieldValue(card, '[data-field="finTotalPayments"]', `$${totalPayments.toFixed(0)}`);
                                                setFieldValue(card, '[data-field="finTotalCost"]', `$${totalCost.toFixed(0)}`);
                                                setFieldValue(card, '[data-field="finCostPerMile"]', `$${costPerMile.toFixed(3)}`);

                                                if (balloonAmount > 0) {
                                                  setFieldValue(card, '[data-field="finBalloonPayment"]', `$${balloonAmount.toFixed(0)}`);
                                                }

                                                return true;
                                              }
function calculateIncentiveDistance(lat1, lon1, lat2, lon2) {
                                                      const R = 3959; // Earth radius in miles
                                                      const dLat = deg2rad(lat2 - lat1);
                                                      const dLon = deg2rad(lon2 - lon1);
                                                      const a =
                                                        Math.sin(dLat / 2) * Math.sin(dLat / 2) +
                                                        Math.cos(deg2rad(lat1)) * Math.cos(deg2rad(lat2)) *
                                                        Math.sin(dLon / 2) * Math.sin(dLon / 2);
                                                      const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
                                                      return R * c;
                                                    }

