function downloadVehicleReport(vehicleId) {
  try {
    const card = document.querySelector(`[data-vehicle-id="${vehicleId}"]`);
    if (!card) {
      showToast('Vehicle not found', 'error');
      return;
    }

    const report = generateVehicleReport(card);
    const fileName = `${report.metadata.make}_${report.metadata.model}_${report.metadata.year}_Report_${new Date().toISOString().split('T')[0]}.txt`;

    // Create blob and download
    const blob = new Blob([report.text], { type: 'text/plain;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = fileName;
    a.click();
    URL.revokeObjectURL(url);

    showToast('Report downloaded successfully', 'success');
  } catch (error) {
    console.error('Download failed:', error);
    showToast('Failed to download report', 'error');
  }
}

