// ==========================================
// 2. CLEAR ALL VEHICLES (COMPLETE)
// ==========================================
function clearAllVehicles() {
  if (!confirm('⚠️ This will remove ALL vehicles and reset the calculator. Are you sure?')) {
    return;
  }

  try {
    // Remove all vehicle cards
    const vehiclesContainer = document.getElementById('vehiclesContainer') || 
                             document.getElementById('vehicles-container');
    if (vehiclesContainer) {
      vehiclesContainer.innerHTML = '';
    }

    // Reset global state
    if (window.vehicles && Array.isArray(window.vehicles)) {
      window.vehicles = [];
    }
    if (typeof window.vehicleCounter !== 'undefined') {
      window.vehicleCounter = 0;
    }

    // Reset comparison section
    const comparisonSection = document.getElementById('comparisonSection') || 
                             document.getElementById('comparison-container');
    if (comparisonSection) {
      comparisonSection.classList.add('hidden');
      comparisonSection.innerHTML = '';
    }

    // Clear all comparison tables
    ['comparisonTableLease', 'comparisonTableVs', 'comparisonTableAll'].forEach(tableId => {
      const table = document.getElementById(tableId);
      if (table) {
        table.innerHTML = '';
      }
    });

    // Add first vehicle back
    if (typeof addVehicle === 'function') {
      addVehicle();
    }

    // Update vehicle counter display
    updateVehicleCount();

    showToast('All vehicles cleared. Starting fresh!', 'success');

  } catch (error) {
    console.error('Error clearing vehicles:', error);
    showToast('Error clearing vehicles', 'error');
  }
}

// ==========================================
// 3. BUILD TABLE (EXTRACTED & ENHANCED)
// ==========================================
function buildTable(config) {
  /**
   * Universal table builder
   * @param {Object} config - Table configuration
   * @param {Array} config.headers - Column headers
   * @param {Array} config.rows - Row data
   * @param {String} config.tableId - ID for the table
   * @param {Object} config.options - Additional options
   */

  const {
    headers = [],
    rows = [],
    tableId = '',
    options = {}
  } = config;

  const {
    highlightBest = true,
    formatters = {},
    classes = {
      table: 'comparison-table',
      header: 'table-header',
      row: 'table-row',
      cell: 'table-cell',
      best: 'better'
    }
  } = options;

  let html = `<table class="${classes.table}" ${tableId ? `id="${tableId}"` : ''}>`;

  // Build header
  html += '<thead><tr>';
  headers.forEach(header => {
    html += `<th class="${classes.header}">${header}</th>`;
  });
  html += '</tr></thead>';

  // Build body
  html += '<tbody>';
  rows.forEach(row => {
    html += `<tr class="${classes.row}">`;

    row.forEach((cell, idx) => {
      // Apply formatter if exists
      const formatter = formatters[headers[idx]] || formatters[idx];
      const displayValue = formatter ? formatter(cell) : cell;

      // Check if this should be highlighted as best
      let cellClass = classes.cell;
      if (highlightBest && cell?.isBest) {
        cellClass += ` ${classes.best}`;
      }

      html += `<td class="${cellClass}">${displayValue}</td>`;
    });

    html += '</tr>';
  });
  html += '</tbody>';

  html += '</table>';

  return html;
}

