// SPECIALIZED TABLE BUILDERS
// ==========================================

function buildLeaseComparisonTable(results) {
  /**
   * Build lease-only comparison table
   */
  const headers = ['Metric', ...results.map(r => `${r.make} ${r.model} #${r.id}`)];

  const metrics = [
    { label: 'Monthly Payment', key: 'totalMonthly', better: 'lower', format: 'currency' },
    { label: 'Due at Signing', key: 'dueAtSigning', better: 'lower', format: 'currency' },
    { label: 'Total Cost', key: 'totalCost', better: 'lower', format: 'currency' },
    { label: 'Buyout', key: 'buyout', better: 'lower', format: 'currency' },
    { label: 'Cost Per Mile', key: 'costPerMile', better: 'lower', format: 'decimal' }
  ];

  const rows = metrics.map(metric => {
    const row = [metric.label];

    // Get values for this metric
    const values = results.filter(r => r.lease).map(r => r.lease[metric.key]);
    const bestValue = metric.better === 'lower' ? 
      Math.min(...values) : Math.max(...values);

    // Build cells
    results.forEach(r => {
      if (!r.lease) {
        row.push('N/A');
        return;
      }

      const value = r.lease[metric.key];
      const isBest = value === bestValue;

      row.push({
        value: value,
        isBest: isBest,
        formatted: metric.format === 'currency' ? 
          formatCurrency(value) : value.toFixed(3)
      });
    });

    return row;
  });

  const formatters = {
    0: (v) => v, // Metric name
    default: (v) => typeof v === 'object' ? v.formatted : v
  };

  // Apply default formatter to all numeric columns
  for (let i = 1; i < headers.length; i++) {
    formatters[i] = formatters.default;
  }

  return buildTable({
    headers,
    rows,
    tableId: 'comparisonTableLease',
    options: {
      highlightBest: true,
      formatters,
      classes: {
        table: 'comparison-table lease-table',
        header: 'table-header',
        row: 'table-row',
        cell: 'table-cell',
        best: 'better'
      }
    }
  });
}

function buildLeaseVsFinanceTable(results) {
  /**
   * Build lease vs finance comparison table
   */
  const headers = ['Vehicle', 'Lease Monthly', 'Finance Monthly', 'Lease Total', 'Finance Total', 'Better Option'];

  const rows = results.map(r => {
    if (!r.lease || !r.finance) {
      return [`${r.make} ${r.model} #${r.id}`, 'N/A', 'N/A', 'N/A', 'N/A', 'N/A'];
    }

    const leaseCost = r.lease.totalCost;
    const financeCost = r.finance.finTotalCost;
    const betterOption = leaseCost < financeCost ? 'LEASE' : 'FINANCE';

    return [
      `${r.make} ${r.model} #${r.id}`,
      { value: r.lease.totalMonthly, formatted: formatCurrency(r.lease.totalMonthly) },
      { value: r.finance.finMonthly, formatted: formatCurrency(r.finance.finMonthly) },
      { value: leaseCost, formatted: formatCurrency(leaseCost), isBest: leaseCost < financeCost },
      { value: financeCost, formatted: formatCurrency(financeCost), isBest: financeCost < leaseCost },
      betterOption
    ];
  });

  const formatters = {
    0: (v) => v,
    default: (v) => typeof v === 'object' ? v.formatted : v
  };

  for (let i = 1; i < headers.length; i++) {
    formatters[i] = formatters.default;
  }

  return buildTable({
    headers,
    rows,
    tableId: 'comparisonTableVs',
    options: {
      highlightBest: true,
      formatters
    }
  });
}

function buildAllMetricsTable(results) {
  /**
   * Build comprehensive metrics table
   */
  const headers = ['Metric', ...results.map(r => `${r.make} ${r.model}`)];

  const allMetrics = [
    { section: 'LEASE', label: 'Monthly Payment', key: 'lease.totalMonthly', format: 'currency' },
    { section: 'LEASE', label: 'Due at Signing', key: 'lease.dueAtSigning', format: 'currency' },
    { section: 'LEASE', label: 'Total Cost', key: 'lease.totalCost', format: 'currency' },
    { section: 'LEASE', label: 'Buyout', key: 'lease.buyout', format: 'currency' },
    { section: 'LEASE', label: 'Cost/Mile', key: 'lease.costPerMile', format: 'decimal' },
    { section: 'FINANCE', label: 'Monthly Payment', key: 'finance.finMonthly', format: 'currency' },
    { section: 'FINANCE', label: 'Total Interest', key: 'finance.finTotalInterest', format: 'currency' },
    { section: 'FINANCE', label: 'Total Cost', key: 'finance.finTotalCost', format: 'currency' },
    { section: 'FINANCE', label: 'Cost/Mile', key: 'finance.finCostPerMile', format: 'decimal' }
  ];

  const rows = allMetrics.map(metric => {
    const row = [`${metric.section}: ${metric.label}`];

    results.forEach(r => {
      const keys = metric.key.split('.');
      let value = r;
      for (const k of keys) {
        value = value?.[k];
      }

      if (value === null || value === undefined) {
        row.push('N/A');
      } else {
        const formatted = metric.format === 'currency' ? 
          formatCurrency(value) : value.toFixed(3);
        row.push(formatted);
      }
    });

    return row;
  });

  return buildTable({
    headers,
    rows,
    tableId: 'comparisonTableAll',
    options: {
      highlightBest: false,
      classes: {
        table: 'comparison-table all-metrics-table'
      }
    }
  });
}

// ==========================================
// HELPER FUNCTIONS
// ==========================================

function formatCurrency(value) {
  if (typeof value !== 'number' || !isFinite(value)) {
    return '--';
  }
  return value.toLocaleString('en-US', {
    style: 'currency',
    currency: 'USD',
    minimumFractionDigits: 0,
    maximumFractionDigits: 0
  });
}

