/**
 * golden_rule_validator.js
 * Validates lease payments against the 1.5% MSRP golden rule
 */

// Golden rule threshold: lease payment should be ≤ 1.5% of MSRP
const GOLDEN_RULE_THRESHOLD = 1.5; // 1.5%

/**
 * Validate lease payment against golden rule
 * @param {number} monthlyPayment - Monthly lease payment
 * @param {number} msrp - Manufacturer's Suggested Retail Price
 * @returns {object} Validation result with pass/fail and percentage
 */
function validateGoldenRule(monthlyPayment, msrp) {
    if (!msrp || msrp <= 0) {
        return {
            valid: false,
            percentage: null,
            passed: false,
            message: 'MSRP required for golden rule validation',
            status: 'error'
        };
    }
    
    const percentage = (monthlyPayment / msrp) * 100;
    const passed = percentage <= GOLDEN_RULE_THRESHOLD;
    
    return {
        valid: true,
        percentage: percentage,
        passed: passed,
        threshold: GOLDEN_RULE_THRESHOLD,
        difference: percentage - GOLDEN_RULE_THRESHOLD,
        monthlyPayment: monthlyPayment,
        msrp: msrp,
        status: passed ? 'pass' : 'fail',
        message: passed 
            ? `✓ Golden Rule PASS: ${percentage.toFixed(2)}% ≤ ${GOLDEN_RULE_THRESHOLD}%`
            : `✗ Golden Rule FAIL: ${percentage.toFixed(2)}% > ${GOLDEN_RULE_THRESHOLD}%`,
        recommendation: passed 
            ? null 
            : calculateGoldenRuleTarget(msrp)
    };
}

/**
 * Calculate target payment to meet golden rule
 * @param {number} msrp - MSRP value
 * @returns {object} Target payment details
 */
function calculateGoldenRuleTarget(msrp) {
    const targetPayment = (msrp * GOLDEN_RULE_THRESHOLD) / 100;
    
    return {
        targetPayment: targetPayment,
        message: `To meet golden rule, payment should be ≤ $${fmt(targetPayment)}/month`
    };
}

/**
 * Suggest adjustments to meet golden rule
 * @param {object} vehicleData - Vehicle calculation data
 * @returns {object} Adjustment suggestions
 */
function suggestGoldenRuleAdjustments(vehicleData) {
    const currentPayment = vehicleData.monthlyPayment;
    const msrp = vehicleData.msrp;
    const targetPayment = (msrp * GOLDEN_RULE_THRESHOLD) / 100;
    const reductionNeeded = currentPayment - targetPayment;
    
    if (reductionNeeded <= 0) {
        return { needed: false };
    }
    
    const suggestions = [];
    
    // Calculate needed selling price reduction
    const term = vehicleData.term || 36;
    const residualPct = vehicleData.residualPct || 50;
    const moneyFactor = vehicleData.moneyFactor || 0.00150;
    
    // Approximate selling price reduction needed
    const depreciationPortion = (100 - residualPct) / 100;
    const monthlyDepreciation = reductionNeeded / (1 + (2 * moneyFactor * term));
    const sellingPriceReduction = (monthlyDepreciation * term) / depreciationPortion;
    
    suggestions.push({
        type: 'selling_price',
        description: 'Negotiate lower selling price',
        amount: sellingPriceReduction,
        impact: `Reduce selling price by ~$${fmt(sellingPriceReduction)}`,
        newTarget: vehicleData.sellingPrice - sellingPriceReduction
    });
    
    // Increased down payment option
    const downPaymentIncrease = reductionNeeded * term;
    suggestions.push({
        type: 'down_payment',
        description: 'Increase down payment',
        amount: downPaymentIncrease,
        impact: `Add $${fmt(downPaymentIncrease)} to down payment`,
        newTarget: vehicleData.downPayment + downPaymentIncrease
    });
    
    // Better money factor
    const currentMF = vehicleData.moneyFactor || 0.00150;
    const targetMFReduction = reductionNeeded / ((vehicleData.sellingPrice + (vehicleData.sellingPrice * residualPct / 100)));
    const targetMF = Math.max(0.00001, currentMF - targetMFReduction);
    
    suggestions.push({
        type: 'money_factor',
        description: 'Negotiate better money factor',
        amount: targetMF,
        impact: `Reduce MF from ${currentMF.toFixed(5)} to ${targetMF.toFixed(5)}`,
        newTarget: targetMF
    });
    
    // Longer term option
    const longerTerm = term + 3;
    const newMonthlyAtLongerTerm = currentPayment * (term / longerTerm) * 1.02; // Rough estimate with slight increase for longer term
    if (newMonthlyAtLongerTerm <= targetPayment) {
        suggestions.push({
            type: 'term',
            description: 'Extend lease term',
            amount: longerTerm,
            impact: `Extend from ${term} to ${longerTerm} months`,
            newTarget: longerTerm,
            estimatedPayment: newMonthlyAtLongerTerm
        });
    }
    
    // Rebates/incentives needed
    suggestions.push({
        type: 'incentives',
        description: 'Apply additional incentives/rebates',
        amount: downPaymentIncrease * 0.7, // Less than down payment option
        impact: `Find $${fmt(downPaymentIncrease * 0.7)} in manufacturer incentives`,
        newTarget: downPaymentIncrease * 0.7
    });
    
    return {
        needed: true,
        reductionNeeded: reductionNeeded,
        targetPayment: targetPayment,
        currentPayment: currentPayment,
        suggestions: suggestions
    };
}

/**
 * Render golden rule badge on vehicle card
 * @param {object} validation - Validation result
 * @param {HTMLElement} container - Container element
 */
function renderGoldenRuleBadge(validation, container) {
    const badge = document.createElement('div');
    badge.className = `golden-rule-badge ${validation.status}`;
    
    if (validation.passed) {
        badge.innerHTML = `
            <div class="golden-badge-pass">
                <div class="golden-icon">✓</div>
                <div class="golden-text">
                    <strong>Golden Rule PASS</strong>
                    <span>${validation.percentage.toFixed(2)}% of MSRP</span>
                </div>
            </div>
        `;
    } else {
        badge.innerHTML = `
            <div class="golden-badge-fail">
                <div class="golden-icon">✗</div>
                <div class="golden-text">
                    <strong>Golden Rule FAIL</strong>
                    <span>${validation.percentage.toFixed(2)}% of MSRP (target: ≤${GOLDEN_RULE_THRESHOLD}%)</span>
                </div>
                <button class="btn-show-adjustments" onclick="showGoldenRuleAdjustments(this)">
                    Show Required Adjustments
                </button>
            </div>
        `;
    }
    
    container.appendChild(badge);
}

/**
 * Show golden rule adjustment suggestions
 * @param {HTMLElement} button - Button element clicked
 */
function showGoldenRuleAdjustments(button) {
    const card = button.closest('.vehicle-card');
    const vehicleIndex = Array.from(card.parentElement.children).indexOf(card);
    const vehicle = vehicles[vehicleIndex];
    
    if (!vehicle || !vehicle.results) {
        showToast('Calculate vehicle first', 'error');
        return;
    }
    
    const adjustments = suggestGoldenRuleAdjustments(vehicle.results);
    
    if (!adjustments.needed) {
        showToast('Vehicle already meets golden rule!', 'success');
        return;
    }
    
    // Create modal with suggestions
    const modal = document.createElement('div');
    modal.className = 'golden-rule-modal';
    modal.innerHTML = `
        <div class="modal-overlay" onclick="this.parentElement.remove()"></div>
        <div class="modal-content golden-adjustments">
            <div class="modal-header">
                <h2>🎯 Golden Rule Adjustments Required</h2>
                <button class="btn-close" onclick="this.closest('.golden-rule-modal').remove()">×</button>
            </div>
            
            <div class="modal-body">
                <div class="adjustment-summary">
                    <div class="current-status">
                        <strong>Current Payment:</strong> $${fmt(adjustments.currentPayment)}/month
                    </div>
                    <div class="target-status">
                        <strong>Target Payment:</strong> $${fmt(adjustments.targetPayment)}/month
                    </div>
                    <div class="reduction-needed">
                        <strong>Reduction Needed:</strong> $${fmt(adjustments.reductionNeeded)}/month
                    </div>
                </div>
                
                <h3>Suggested Adjustments:</h3>
                <div class="suggestions-list">
                    ${adjustments.suggestions.map((suggestion, idx) => `
                        <div class="suggestion-card" data-type="${suggestion.type}">
                            <div class="suggestion-number">${idx + 1}</div>
                            <div class="suggestion-content">
                                <h4>${suggestion.description}</h4>
                                <p class="suggestion-impact">${suggestion.impact}</p>
                                ${suggestion.estimatedPayment ? `
                                    <p class="estimated-result">
                                        Estimated new payment: $${fmt(suggestion.estimatedPayment)}/month
                                    </p>
                                ` : ''}
                                <button class="btn-apply-suggestion" 
                                        onclick="applyGoldenRuleSuggestion(${vehicleIndex}, '${suggestion.type}', ${suggestion.newTarget})">
                                    Apply This Adjustment
                                </button>
                            </div>
                        </div>
                    `).join('')}
                </div>
            </div>
        </div>
    `;
    
    document.body.appendChild(modal);
}

/**
 * Apply golden rule suggestion to vehicle
 * @param {number} vehicleIndex - Index of vehicle
 * @param {string} type - Type of adjustment
 * @param {number} newValue - New value to apply
 */
function applyGoldenRuleSuggestion(vehicleIndex, type, newValue) {
    const card = document.querySelectorAll('.vehicle-card')[vehicleIndex];
    if (!card) return;
    
    switch(type) {
        case 'selling_price':
            setFieldValue(card, '.sellingPrice', newValue);
            break;
        case 'down_payment':
            setFieldValue(card, '.downPayment', newValue);
            break;
        case 'money_factor':
            setFieldValue(card, '.moneyFactor', newValue);
            break;
        case 'term':
            setFieldValue(card, '.term', newValue);
            break;
        case 'incentives':
            showToast(`Find $${fmt(newValue)} in incentives/rebates to add`, 'info');
            break;
    }
    
    // Close modal
    document.querySelector('.golden-rule-modal')?.remove();
    
    // Recalculate
    calculateVehicle(vehicleIndex);
    
    showToast(`Adjustment applied. Recalculating...`, 'success');
}

