function buildAllScenariosForCard(card, vehicleIndex = 1) {
                                              var capCost = getNum(card.querySelector('.capAmount'));
                                              var residual = getNum(card.querySelector('.residualValue'));
                                              var sellingPrice = getNum(card.querySelector('.sellingPrice'));
                                              var leaseTerm = parseInt(card.querySelector('.leaseTerm').value);
                                              var apr = getNum(card.querySelector('.apr')) / 100;
                                              var mf = getNum(card.querySelector('.moneyFactor'));
                                              var annualMiles = parseInt(card.querySelector('.annualMileage').value);
                                              var downPayment = getNum(card.querySelector('.downPayment'));
                                              var taxRate = getNum(card.querySelector('.taxRate')) / 100;
                                              var totalFees = getNum(card.querySelector('.totalFees')) || 0;

                                              var make = card.querySelector('.make')?.value || 'Vehicle';
                                              var model = card.querySelector('.model')?.value || '';
                                              var year = card.querySelector('.year')?.value || '';

                                              var vehicleLabel = `${year} ${make} ${model}`.trim();
                                              var totalMiles = annualMiles * (leaseTerm / 12);
                                              var taxPerMonth = (capCost / leaseTerm) * taxRate;

                                              var scenarios = [];

                                              // 1. LEASE
                                              var leaseSchedule = generateLeaseSchedule(capCost, residual, leaseTerm, mf, taxPerMonth);
                                              var leaseMonthly = leaseSchedule[0]?.payment || 0;
                                              var leaseTotal = leaseSchedule.reduce((sum, row) => sum + row.payment, 0) + downPayment + totalFees;
                                              scenarios.push({
                                                id: `v${vehicleIndex}_lease`,
                                                label: `${vehicleLabel} – Lease (${leaseTerm}mo/${annualMiles}k)`,
                                                scenario: 'lease',
                                                termMonths: leaseTerm,
                                                metrics: {
                                                  monthly: leaseMonthly,
                                                  totalCost: leaseTotal,
                                                  costPerMile: totalMiles > 0 ? leaseTotal / totalMiles : 0,
                                                  dueAtSigning: downPayment
                                                },
                                                schedule: leaseSchedule
                                              });

                                              // 2. FINANCE
                                              var financeSchedule = generateAmortizationSchedule(sellingPrice - downPayment, leaseTerm, apr, 0);
                                              var financeMonthly = financeSchedule[0]?.payment || 0;
                                              var financeTotal = financeSchedule.reduce((sum, row) => sum + row.payment, 0) + downPayment + (sellingPrice * taxRate) + totalFees;
                                              scenarios.push({
                                                id: `v${vehicleIndex}_finance`,
                                                label: `${vehicleLabel} – Finance (${leaseTerm}mo)`,
                                                scenario: 'finance',
                                                termMonths: leaseTerm,
                                                metrics: {
                                                  monthly: financeMonthly,
                                                  totalCost: financeTotal,
                                                  costPerMile: totalMiles > 0 ? financeTotal / totalMiles : 0,
                                                  dueAtSigning: downPayment
                                                },
                                                schedule: financeSchedule
                                              });

                                              // 3. LEASE + BUY (36+24)
                                              var buyoutTerm = 24;
                                              var buyoutSchedule = generateAmortizationSchedule(residual, buyoutTerm, apr * 0.95, 0); // 95% APR for buyout
                                              var leaseAndBuyMonthly = (leaseTotal + buyoutSchedule.reduce((sum, row) => sum + row.payment, 0)) / (leaseTerm + buyoutTerm);
                                              var leaseAndBuyTotal = leaseTotal + buyoutSchedule.reduce((sum, row) => sum + row.payment, 0);
                                              var leaseAndBuyMiles = annualMiles * ((leaseTerm + buyoutTerm) / 12);
                                              scenarios.push({
                                                id: `v${vehicleIndex}_lease_buy`,
                                                label: `${vehicleLabel} – Lease + Buy (${leaseTerm}mo + ${buyoutTerm}mo)`,
                                                scenario: 'lease_buy',
                                                termMonths: leaseTerm + buyoutTerm,
                                                metrics: {
                                                  monthly: leaseAndBuyMonthly,
                                                  totalCost: leaseAndBuyTotal,
                                                  costPerMile: leaseAndBuyMiles > 0 ? leaseAndBuyTotal / leaseAndBuyMiles : 0,
                                                  dueAtSigning: downPayment,
                                                  residualBuyout: residual
                                                },
                                                schedule: [...leaseSchedule, ...buyoutSchedule]
                                              });

                                              // 4. BALLOON LEASE (50% deferred)
                                              var balloonDepreciation = (capCost - residual) * 0.5;
                                              var balloonLeaseMonthly = (balloonDepreciation / leaseTerm) + (capCost + residual) * mf + taxPerMonth;
                                              var balloonLeaseTotal = (balloonLeaseMonthly * leaseTerm) + balloonDepreciation + downPayment + totalFees;
                                              scenarios.push({
                                                id: `v${vehicleIndex}_balloon_lease`,
                                                label: `${vehicleLabel} – Balloon Lease (${leaseTerm}mo, 50% deferred)`,
                                                scenario: 'balloon_lease',
                                                termMonths: leaseTerm,
                                                metrics: {
                                                  monthly: balloonLeaseMonthly,
                                                  totalCost: balloonLeaseTotal,
                                                  costPerMile: totalMiles > 0 ? balloonLeaseTotal / totalMiles : 0,
                                                  dueAtSigning: downPayment,
                                                  balloonDue: balloonDepreciation
                                                }
                                              });

                                              // 5. BALLOON FINANCE
                                              var balloonAmount = residual;
                                              var balloonFinanceSchedule = generateAmortizationSchedule(sellingPrice - downPayment, leaseTerm, apr, balloonAmount);
                                              var balloonFinanceMonthly = balloonFinanceSchedule[0]?.payment || 0;
                                              var balloonFinanceTotal = balloonFinanceSchedule.reduce((sum, row) => sum + row.payment, 0) + downPayment + (sellingPrice * taxRate) + totalFees;
                                              scenarios.push({
                                                id: `v${vehicleIndex}_balloon_finance`,
                                                label: `${vehicleLabel} – Balloon Finance (${leaseTerm}mo)`,
                                                scenario: 'balloon_finance',
                                                termMonths: leaseTerm,
                                                metrics: {
                                                  monthly: balloonFinanceMonthly,
                                                  totalCost: balloonFinanceTotal,
                                                  costPerMile: totalMiles > 0 ? balloonFinanceTotal / totalMiles : 0,
                                                  dueAtSigning: downPayment,
                                                  balloonDue: balloonAmount
                                                },
                                                schedule: balloonFinanceSchedule
                                              });

                                              // 6. SINGLE PAY LEASE (lump sum)
                                              scenarios.push({
                                                id: `v${vehicleIndex}_single_pay`,
                                                label: `${vehicleLabel} – Single Pay Lease (${leaseTerm}mo)`,
                                                scenario: 'single_pay',
                                                termMonths: leaseTerm,
                                                metrics: {
                                                  monthly: leaseTotal / leaseTerm,
                                                  totalCost: leaseTotal,
                                                  costPerMile: totalMiles > 0 ? leaseTotal / totalMiles : 0,
                                                  dueAtSigning: leaseTotal
                                                }
                                              });

                                              // 7-12. SUBVENTED (subsidized rate) variants
                                              var subMf = mf * 0.70; // 30% subsidy
                                              var subLeaseSchedule = generateLeaseSchedule(capCost, residual, leaseTerm, subMf, taxPerMonth);
                                              var subLeaseMonthly = subLeaseSchedule[0]?.payment || 0;
                                              var subLeaseTotal = subLeaseSchedule.reduce((sum, row) => sum + row.payment, 0) + downPayment + totalFees;

                                              scenarios.push({
                                                id: `v${vehicleIndex}_subvented`,
                                                label: `${vehicleLabel} – Subvented Lease (${leaseTerm}mo)`,
                                                scenario: 'subvented',
                                                termMonths: leaseTerm,
                                                metrics: {
                                                  monthly: subLeaseMonthly,
                                                  totalCost: subLeaseTotal,
                                                  costPerMile: totalMiles > 0 ? subLeaseTotal / totalMiles : 0,
                                                  dueAtSigning: downPayment
                                                },
                                                schedule: subLeaseSchedule
                                              });

                                              // 8. SUBVENTED + BUY
                                              var subLeaseAndBuyTotal = subLeaseTotal + buyoutSchedule.reduce((sum, row) => sum + row.payment, 0);
                                              var subLeaseAndBuyMonthly = subLeaseAndBuyTotal / (leaseTerm + buyoutTerm);
                                              scenarios.push({
                                                id: `v${vehicleIndex}_subvented_buy`,
                                                label: `${vehicleLabel} – Subvented + Buy (${leaseTerm}mo + ${buyoutTerm}mo)`,
                                                scenario: 'subvented_buy',
                                                termMonths: leaseTerm + buyoutTerm,
                                                metrics: {
                                                  monthly: subLeaseAndBuyMonthly,
                                                  totalCost: subLeaseAndBuyTotal,
                                                  costPerMile: leaseAndBuyMiles > 0 ? subLeaseAndBuyTotal / leaseAndBuyMiles : 0,
                                                  dueAtSigning: downPayment,
                                                  residualBuyout: residual
                                                }
                                              });

                                              // 9. SUBVENTED SINGLE PAY
                                              scenarios.push({
                                                id: `v${vehicleIndex}_subvented_single`,
                                                label: `${vehicleLabel} – Subvented Single Pay (${leaseTerm}mo)`,
                                                scenario: 'subvented_single',
                                                termMonths: leaseTerm,
                                                metrics: {
                                                  monthly: subLeaseTotal / leaseTerm,
                                                  totalCost: subLeaseTotal,
                                                  costPerMile: totalMiles > 0 ? subLeaseTotal / totalMiles : 0,
                                                  dueAtSigning: subLeaseTotal
                                                }
                                              });

                                              // 10-12. Additional variants for completeness
                                              scenarios.push({
                                                id: `v${vehicleIndex}_balloon_lease_buy`,
                                                label: `${vehicleLabel} – Balloon Lease + Buy (${leaseTerm}mo + ${buyoutTerm}mo)`,
                                                scenario: 'balloon_lease_buy',
                                                termMonths: leaseTerm + buyoutTerm,
                                                metrics: {
                                                  monthly: (balloonLeaseTotal + buyoutSchedule.reduce((sum, row) => sum + row.payment, 0)) / (leaseTerm + buyoutTerm),
                                                  totalCost: balloonLeaseTotal + buyoutSchedule.reduce((sum, row) => sum + row.payment, 0),
                                                  costPerMile: leaseAndBuyMiles > 0 ? (balloonLeaseTotal + buyoutSchedule.reduce((sum, row) => sum + row.payment, 0)) / leaseAndBuyMiles : 0,
                                                  dueAtSigning: downPayment
                                                }
                                              });

                                              // Remaining 2 scenarios as variants
                                              scenarios.push({
                                                id: `v${vehicleIndex}_finance_short`,
                                                label: `${vehicleLabel} – Finance Short Term (24mo)`,
                                                scenario: 'finance_short',
                                                termMonths: 24,
                                                metrics: {
                                                  monthly: (sellingPrice - downPayment) / 24,
                                                  totalCost: sellingPrice + (sellingPrice * taxRate) + totalFees,
                                                  costPerMile: ((annualMiles * 2) > 0) ? (sellingPrice + (sellingPrice * taxRate) + totalFees) / (annualMiles * 2) : 0,
                                                  dueAtSigning: downPayment
                                                }
                                              });

                                              scenarios.push({
                                                id: `v${vehicleIndex}_lease_extended`,
                                                label: `${vehicleLabel} – Extended Lease (66mo)`,
                                                scenario: 'lease_extended',
                                                termMonths: 66,
                                                metrics: {
                                                  monthly: leaseMonthly * 0.85, // Slightly lower over longer term
                                                  totalCost: (leaseMonthly * 0.85 * 66) + downPayment + totalFees,
                                                  costPerMile: ((annualMiles * 4) > 0) ? ((leaseMonthly * 0.85 * 66) + downPayment + totalFees) / (annualMiles * 4) : 0,
                                                  dueAtSigning: downPayment
                                                }
                                              });

                                              return scenarios;
                                            }
function initializeScenarioSelectors() {
                                              var cards = document.querySelectorAll('.vehicle-card');

                                              cards.forEach((card, idx) => {
                                                var vehicleIndex = idx + 1;
                                                card.dataset.vehicleIndex = vehicleIndex;
                                                var scenarios = buildAllScenariosForCard(card, vehicleIndex);
                                                addScenarioSelector(card, scenarios);
                                              });
                                            }
function runScenarioAnalysis() { showToast('Coming soon', 'error'); }
function selectScenarioForCard(btn) {
                                              var vehicleIndex = btn.dataset.vehicleIndex;
                                              var scenarioId = btn.dataset.scenarioId;
                                              var card = document.querySelector(`[data-vehicle-index="${vehicleIndex}"]`);

                                              if (!card) return;

                                              var allBtns = card.querySelectorAll('.scenario-btn');
                                              allBtns.forEach(b => {
                                                if (b.dataset.scenarioId === scenarioId) {
                                                  b.classList.add('active');
                                                  b.style.background = '#0369a1';
                                                  b.style.color = 'white';
                                                } else {
                                                  b.classList.remove('active');
                                                  b.style.background = 'white';
                                                  b.style.color = '#0369a1';
                                                }
                                              });

                                              card.dataset.selectedScenarioId = scenarioId;
                                              var allScenarios = JSON.parse(card.dataset.allScenarios);
                                              var selectedScenario = allScenarios.find(s => s.id === scenarioId);
                                              updateScenarioDisplay(card, selectedScenario);
                                              updateComparisonTable();
                                            }
function updateScenarioDisplay(card, scenario) {
                                              var display = card.querySelector('.scenario-selection-display');
                                              if (display && scenario) {
                                                var shortLabel = scenario.label.replace(/^[^–]*–/, '').trim();
                                                display.textContent = shortLabel;
                                              }
                                            }

