/**
 * Load scenarios from JSON file
 */
async function loadScenarios() {
    try {
        // Try to load from external JSON file
        const response = await fetch('/mnt/user-data/uploads/scenariolist.json')
            .catch(() => fetch('./scenariolist.json'))
            .catch(() => fetch('./data/scenariolist.json'));
        
        if (response.ok) {
            SCENARIOS_LIST = await response.json();
            console.log(`✓ Loaded ${SCENARIOS_LIST.length} scenarios from JSON`);
        } else {
            throw new Error('Failed to load scenariolist.json');
        }
    } catch (error) {
        console.warn('Could not load scenariolist.json, using embedded scenarios:', error);
        SCENARIOS_LIST = EMBEDDED_SCENARIOS;
    }
    
    // Populate all scenario selectors on the page
    populateAllScenarioSelectors();
    
    return SCENARIOS_LIST;
}

/**
 * Populate all scenario select dropdowns
 */
function populateAllScenarioSelectors() {
    const selectors = document.querySelectorAll('.scenarioSelect');
    
    selectors.forEach(selector => {
        populateScenarioSelector(selector);
    });
    
    console.log(`✓ Populated ${selectors.length} scenario selectors`);
}

/**
 * Populate a single scenario selector
 * @param {HTMLElement} selector - Select element
 */
function populateScenarioSelector(selector) {
    if (!selector) return;
    
    // Clear existing options except the first (placeholder)
    while (selector.options.length > 1) {
        selector.remove(1);
    }
    
    // Group scenarios by category
    const categorized = {};
    SCENARIOS_LIST.forEach(scenario => {
        const category = scenario.category || 'Other';
        if (!categorized[category]) {
            categorized[category] = [];
        }
        categorized[category].push(scenario);
    });
    
    // Add scenarios by category
    Object.keys(categorized).sort().forEach(category => {
        const optgroup = document.createElement('optgroup');
        optgroup.label = category;
        
        categorized[category].forEach(scenario => {
            const option = document.createElement('option');
            option.value = scenario.id;
            option.textContent = `${scenario.id}. ${scenario.title}`;
            option.dataset.scenarioData = JSON.stringify(scenario);
            optgroup.appendChild(option);
        });
        
        selector.appendChild(optgroup);
    });
    
    // Add change event listener
    selector.addEventListener('change', handleScenarioSelection);
}

/**
 * Handle scenario selection
 * @param {Event} event - Change event
 */
function handleScenarioSelection(event) {
    const selector = event.target;
    const card = selector.closest('.vehicle-card');
    
    if (!card) return;
    
    const selectedOption = selector.options[selector.selectedIndex];
    
    if (!selectedOption || !selectedOption.value) {
        // Hide details if no scenario selected
        const detailsDiv = card.querySelector('.scenario-details');
        if (detailsDiv) {
            detailsDiv.classList.add('hidden');
        }
        return;
    }
    
    const scenarioData = JSON.parse(selectedOption.dataset.scenarioData || '{}');
    
    // Display scenario details
    displayScenarioDetails(card, scenarioData);
}

/**
 * Display scenario details
 * @param {HTMLElement} card - Vehicle card element
 * @param {object} scenario - Scenario data
 */
function displayScenarioDetails(card, scenario) {
    const detailsDiv = card.querySelector('.scenario-details');
    const infoDiv = card.querySelector('.scenario-info');
    
    if (!detailsDiv || !infoDiv) return;
    
    // Show details section
    detailsDiv.classList.remove('hidden');
    
    // Populate details
    infoDiv.innerHTML = `
        <div class="scenario-detail-content">
            <div class="scenario-header">
                <span class="scenario-id">Scenario #${scenario.id}</span>
                <span class="scenario-category">${scenario.category}</span>
            </div>
            
            <h5 style="color: var(--secondary); margin: 10px 0;">${scenario.title}</h5>
            
            <p style="color: #6b7280; line-height: 1.6; margin: 10px 0;">
                ${scenario.description}
            </p>
            
            <div class="scenario-meta" style="margin-top: 15px;">
                <div class="meta-item">
                    <strong>Analysis Areas:</strong>
                    <div class="tag-list">
                        ${scenario.arenas.map(arena => `
                            <span class="arena-tag">${arena}</span>
                        `).join('')}
                    </div>
                </div>
                
                <div class="meta-item" style="margin-top: 10px;">
                    <strong>Key Factors:</strong>
                    <div class="tag-list">
                        ${scenario.tags.map(tag => `
                            <span class="factor-tag">${tag}</span>
                        `).join('')}
                    </div>
                </div>
            </div>
        </div>
    `;
    
    // Store scenario data on card for applyScenario function
    card.dataset.currentScenario = JSON.stringify(scenario);
}

/**
 * Apply scenario to vehicle (enhanced version)
 * @param {HTMLElement} button - Button element clicked
 */
/**
 * Generate scenario-specific analysis
 * @param {object} scenario - Scenario data
 * @param {object} vehicle - Vehicle data
 * @returns {object} Analysis result with HTML
 */
function generateScenarioAnalysis(scenario, vehicle) {
    if (!vehicle || !vehicle.results) {
        return {
            html: '<p style="color: #ef4444;">Please calculate vehicle first before applying scenario.</p>'
        };
    }
    
    // Generic analysis template (can be enhanced per scenario type)
    const baseResults = vehicle.results;
    
    let html = `
        <div class="scenario-results-grid">
            <div class="result-section">
                <h6>Base Vehicle Analysis</h6>
                <div class="result-row">
                    <span>Deal Type:</span>
                    <strong>${baseResults.dealType || 'N/A'}</strong>
                </div>
                <div class="result-row">
                    <span>Monthly Payment:</span>
                    <strong>$${fmt(baseResults.monthlyPayment || 0)}</strong>
                </div>
                <div class="result-row">
                    <span>Total Cost (${baseResults.term}mo):</span>
                    <strong>$${fmt((baseResults.monthlyPayment || 0) * (baseResults.term || 36))}</strong>
                </div>
            </div>
            
            <div class="result-section">
                <h6>Scenario-Specific Insights</h6>
    `;
    
    // Add scenario-specific analysis based on category/tags
    if (scenario.tags.includes('gig') || scenario.tags.includes('business')) {
        const annualMiles = vehicle.annualMileage || 12000;
        const monthlyMiles = annualMiles / 12;
        const costPerMile = baseResults.monthlyPayment / monthlyMiles;
        
        html += `
            <div class="result-row">
                <span>Cost per Mile:</span>
                <strong>$${costPerMile.toFixed(3)}</strong>
            </div>
            <div class="result-row">
                <span>Annual Mileage:</span>
                <strong>${fmt(annualMiles)} miles</strong>
            </div>
            <div class="result-row">
                <span>Est. Annual Vehicle Cost:</span>
                <strong>$${fmt(baseResults.monthlyPayment * 12)}</strong>
            </div>
            ${scenario.tags.includes('tax') ? `
            <div class="result-row highlight">
                <span>Potential Tax Deduction (30%):</span>
                <strong>$${fmt(baseResults.monthlyPayment * 12 * 0.30)}/year</strong>
            </div>
            ` : ''}
        `;
    }
    
    if (scenario.tags.includes('ev') || scenario.tags.includes('energy')) {
        if (baseResults.energyCost) {
            html += `
                <div class="result-row">
                    <span>Annual Energy Cost:</span>
                    <strong>$${fmt(baseResults.energyCost)}</strong>
                </div>
            `;
        }
    }
    
    if (scenario.tags.includes('insurance')) {
        // Estimate insurance impact
        const estimatedInsurance = vehicle.msrp * 0.01 * 12; // Rough 1% of MSRP per year
        html += `
            <div class="result-row">
                <span>Est. Annual Insurance:</span>
                <strong>$${fmt(estimatedInsurance)}</strong>
            </div>
            <div class="result-row">
                <span>Total Annual Ownership:</span>
                <strong>$${fmt(baseResults.monthlyPayment * 12 + estimatedInsurance)}</strong>
            </div>
        `;
    }
    
    html += `
            </div>
            
            <div class="result-section">
                <h6>Recommendations</h6>
                <ul class="scenario-recommendations">
                    ${generateRecommendations(scenario, vehicle).map(rec => `
                        <li>${rec}</li>
                    `).join('')}
                </ul>
            </div>
        </div>
    `;
    
    return { html };
}

/**
 * Generate scenario-specific recommendations
 * @param {object} scenario - Scenario data
 * @param {object} vehicle - Vehicle data
 * @returns {array} Recommendations
 */
function generateRecommendations(scenario, vehicle) {
    const recommendations = [];
    
    if (scenario.tags.includes('business') || scenario.tags.includes('fleet')) {
        recommendations.push('Consider Section 179 deduction if purchasing for business use');
        recommendations.push('Consult tax professional for optimal expense vs. mileage deduction');
        if (vehicle.results.dealType === 'lease') {
            recommendations.push('Lease payments are typically 100% deductible for business use');
        }
    }
    
    if (scenario.tags.includes('gig')) {
        recommendations.push('Track all mileage meticulously for tax purposes');
        recommendations.push('Consider commercial insurance or rideshare endorsement');
        recommendations.push('Factor in accelerated depreciation from high mileage');
    }
    
    if (scenario.tags.includes('ev') || scenario.category === 'Electric Vehicle') {
        recommendations.push('Verify home charging installation costs and capabilities');
        recommendations.push('Research public charging availability in your area');
        recommendations.push('Consider time-of-use electricity rates for optimal savings');
    }
    
    if (scenario.tags.includes('climate')) {
        recommendations.push('Research vehicle performance in your local climate conditions');
        recommendations.push('Factor in climate-specific maintenance costs (e.g., winter tires)');
    }
    
    if (recommendations.length === 0) {
        recommendations.push('Review all financial details carefully before committing');
        recommendations.push('Compare this scenario with others to find optimal strategy');
        recommendations.push('Consult with relevant professionals for specific advice');
    }
    
    return recommendations;
}

/**
 * Export scenario results
 * @param {number} vehicleIndex - Vehicle index
 * @param {number} scenarioId - Scenario ID
 */
function exportScenarioResults(vehicleIndex, scenarioId) {
    const vehicle = vehicles[vehicleIndex];
    const scenario = SCENARIOS_LIST.find(s => s.id === scenarioId);
    
    if (!vehicle || !scenario) {
        showToast('Error exporting scenario results', 'error');
        return;
    }
    
    const exportData = {
        scenario: scenario,
        vehicle: {
            year: vehicle.year,
            make: vehicle.make,
            model: vehicle.model,
            trim: vehicle.trim
        },
        results: vehicle.results,
        analysis: generateScenarioAnalysis(scenario, vehicle),
        exportedAt: new Date().toISOString()
    };
    
    // Create download
    const blob = new Blob([JSON.stringify(exportData, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `scenario_${scenarioId}_vehicle_${vehicleIndex + 1}_${Date.now()}.json`;
    a.click();
    URL.revokeObjectURL(url);
    
    showToast('Scenario results exported!', 'success');
}

/**
 * Compare scenario across multiple vehicles
 * @param {number} vehicleIndex - Current vehicle index
 * @param {number} scenarioId - Scenario ID
 */
function compareWithOtherVehicles(vehicleIndex, scenarioId) {
    const scenario = SCENARIOS_LIST.find(s => s.id === scenarioId);
    
    if (!scenario) {
        showToast('Scenario not found', 'error');
        return;
    }
    
    // Apply scenario to all calculated vehicles
    const comparisonResults = vehicles.map((vehicle, idx) => {
        if (!vehicle.results) return null;
        
        return {
            index: idx,
            name: `${vehicle.year} ${vehicle.make} ${vehicle.model}`,
            analysis: generateScenarioAnalysis(scenario, vehicle)
        };
    }).filter(r => r !== null);
    
    if (comparisonResults.length < 2) {
        showToast('Calculate at least 2 vehicles to compare', 'warning');
        return;
    }
    
    // Show comparison modal
    showScenarioComparisonModal(scenario, comparisonResults);
}

/**
 * Show scenario comparison modal
 * @param {object} scenario - Scenario data
 * @param {array} results - Comparison results
 */
function showScenarioComparisonModal(scenario, results) {
    const modal = document.createElement('div');
    modal.className = 'scenario-comparison-modal';
    modal.innerHTML = `
        <div class="modal-overlay" onclick="this.parentElement.remove()"></div>
        <div class="modal-content scenario-comparison">
            <div class="modal-header">
                <h2>📊 Scenario Comparison: ${scenario.title}</h2>
                <button class="btn-close" onclick="this.closest('.scenario-comparison-modal').remove()">×</button>
            </div>
            
            <div class="modal-body">
                <div class="comparison-container">
                    ${results.map(result => `
                        <div class="comparison-card">
                            <h4>Vehicle #${result.index + 1}: ${result.name}</h4>
                            ${result.analysis.html}
                        </div>
                    `).join('')}
                </div>
            </div>
        </div>
    `;
    
    document.body.appendChild(modal);
}

