/**
 * trade_optimizer.js
 * Analyzes optimal trade equity application across multiple vehicles
 */

/**
 * Analyze trade equity optimization across all vehicles
 * @returns {object} Trade optimization analysis
 */
function analyzeTradeOptimization() {
    if (vehicles.length < 2) {
        return {
            valid: false,
            message: 'Need at least 2 vehicles to compare trade optimization'
        };
    }
    
    // Get vehicles with calculated results
    const validVehicles = vehicles
        .map((v, idx) => ({ ...v, index: idx }))
        .filter(v => v.results && v.results.dealType === 'lease');
    
    if (validVehicles.length < 2) {
        return {
            valid: false,
            message: 'Need at least 2 calculated lease vehicles for trade optimization'
        };
    }
    
    // Calculate trade equity for each vehicle
    const tradeEquity = validVehicles[0].tradein - validVehicles[0].tradePayoff;
    
    if (tradeEquity <= 0) {
        return {
            valid: false,
            message: 'No positive trade equity available to optimize',
            tradeEquity: tradeEquity
        };
    }
    
    // Analyze each vehicle's benefit from trade equity
    const scenarios = validVehicles.map(vehicle => {
        return analyzeTradeEquityScenarios(vehicle, tradeEquity, validVehicles);
    });
    
    // Find optimal distribution
    const optimalStrategy = findOptimalTradeDistribution(scenarios, tradeEquity);
    
    return {
        valid: true,
        tradeEquity: tradeEquity,
        scenarios: scenarios,
        optimalStrategy: optimalStrategy,
        recommendation: generateTradeRecommendation(optimalStrategy)
    };
}

/**
 * Analyze trade equity scenarios for a single vehicle
 * @param {object} vehicle - Vehicle data
 * @param {number} totalTradeEquity - Total trade equity available
 * @param {array} allVehicles - All vehicles for comparison
 * @returns {object} Scenario analysis
 */
function analyzeTradeEquityScenarios(vehicle, totalTradeEquity, allVehicles) {
    const basePayment = vehicle.results.monthlyPayment;
    const baseCapCost = vehicle.results.netCapCost;
    const msrp = vehicle.msrp || vehicle.results.msrp;
    
    // Scenario 1: Apply all trade equity to this vehicle
    const fullTradeScenario = calculateTradeImpact(vehicle, totalTradeEquity);
    
    // Scenario 2: Apply partial trade equity
    const partialTradeScenario = calculateTradeImpact(vehicle, totalTradeEquity / 2);
    
    // Scenario 3: Apply no trade equity
    const noTradeScenario = {
        appliedEquity: 0,
        newPayment: basePayment,
        paymentReduction: 0,
        newCapCost: baseCapCost,
        percentageReduction: 0,
        goldenRuleImpact: validateGoldenRule(basePayment, msrp)
    };
    
    // Calculate value score for this vehicle receiving trade
    const valueScore = calculateTradeValueScore(vehicle, fullTradeScenario);
    
    return {
        vehicleIndex: vehicle.index,
        vehicleName: `${vehicle.year} ${vehicle.make} ${vehicle.model}`,
        basePayment: basePayment,
        msrp: msrp,
        scenarios: {
            full: fullTradeScenario,
            partial: partialTradeScenario,
            none: noTradeScenario
        },
        valueScore: valueScore,
        tradeEfficiency: fullTradeScenario.paymentReduction / totalTradeEquity,
        goldenRuleStatus: noTradeScenario.goldenRuleImpact.passed ? 'pass' : 'fail'
    };
}

/**
 * Calculate impact of applying trade equity to vehicle
 * @param {object} vehicle - Vehicle data
 * @param {number} tradeEquity - Trade equity to apply
 * @returns {object} Impact analysis
 */
function calculateTradeImpact(vehicle, tradeEquity) {
    const results = vehicle.results;
    const term = results.term || 36;
    const moneyFactor = results.moneyFactor || 0.00150;
    const residualValue = results.residualValue;
    const msrp = vehicle.msrp || results.msrp;
    
    // New capitalized cost with trade equity applied
    const newCapCost = results.netCapCost - tradeEquity;
    
    // Recalculate monthly depreciation
    const newDepreciation = newCapCost - residualValue;
    const newMonthlyDep = newDepreciation / term;
    
    // Rent charge changes with new cap cost
    const newRentCharge = (newCapCost + residualValue) * moneyFactor;
    
    // New monthly payment
    const newMonthlyPayment = newMonthlyDep + newRentCharge;
    
    // Calculate savings
    const paymentReduction = results.monthlyPayment - newMonthlyPayment;
    const percentageReduction = (paymentReduction / results.monthlyPayment) * 100;
    
    // Check golden rule with new payment
    const goldenRuleImpact = validateGoldenRule(newMonthlyPayment, msrp);
    
    // Calculate total lease cost savings
    const totalSavings = paymentReduction * term;
    
    return {
        appliedEquity: tradeEquity,
        newCapCost: newCapCost,
        newMonthlyPayment: newMonthlyPayment,
        paymentReduction: paymentReduction,
        percentageReduction: percentageReduction,
        totalSavings: totalSavings,
        goldenRuleImpact: goldenRuleImpact,
        goldenRuleImprovement: goldenRuleImpact.passed && !validateGoldenRule(results.monthlyPayment, msrp).passed,
        effectiveDiscount: (tradeEquity / newMonthlyPayment).toFixed(1) + ' months free'
    };
}

/**
 * Calculate value score for applying trade to this vehicle
 * @param {object} vehicle - Vehicle data
 * @param {object} scenario - Trade scenario
 * @returns {number} Value score (0-100)
 */
function calculateTradeValueScore(vehicle, scenario) {
    let score = 0;
    
    // Factor 1: Payment reduction efficiency (0-30 points)
    const efficiencyScore = Math.min(30, (scenario.paymentReduction / scenario.appliedEquity) * 10000);
    score += efficiencyScore;
    
    // Factor 2: Golden rule impact (0-25 points)
    if (scenario.goldenRuleImprovement) {
        score += 25; // Big bonus for achieving golden rule
    } else if (scenario.goldenRuleImpact.passed) {
        score += 15; // Good but was already passing
    } else {
        // Partial credit for getting closer
        const improvement = scenario.goldenRuleImpact.percentage < validateGoldenRule(vehicle.results.monthlyPayment, vehicle.msrp).percentage;
        score += improvement ? 10 : 0;
    }
    
    // Factor 3: Percentage payment reduction (0-25 points)
    const pctScore = Math.min(25, scenario.percentageReduction);
    score += pctScore;
    
    // Factor 4: Vehicle class/value (0-20 points)
    const msrp = vehicle.msrp || vehicle.results.msrp;
    if (msrp > 60000) {
        score += 20; // Luxury vehicle
    } else if (msrp > 40000) {
        score += 15; // Mid-range
    } else {
        score += 10; // Economy
    }
    
    return Math.min(100, score);
}

/**
 * Find optimal trade equity distribution
 * @param {array} scenarios - All vehicle scenarios
 * @param {number} totalTradeEquity - Total equity available
 * @returns {object} Optimal strategy
 */
function findOptimalTradeDistribution(scenarios, totalTradeEquity) {
    // Sort by value score
    const ranked = [...scenarios].sort((a, b) => b.valueScore - a.valueScore);
    
    // Strategy 1: All to highest value vehicle
    const allToTop = {
        type: 'single',
        primary: ranked[0].vehicleIndex,
        allocation: {
            [ranked[0].vehicleIndex]: totalTradeEquity
        },
        totalSavings: ranked[0].scenarios.full.totalSavings,
        description: `Apply all $${fmt(totalTradeEquity)} to ${ranked[0].vehicleName}`
    };
    
    // Strategy 2: Split between top two
    if (scenarios.length >= 2) {
        const split1 = totalTradeEquity * 0.7;
        const split2 = totalTradeEquity * 0.3;
        
        const impact1 = calculateTradeImpact(vehicles[ranked[0].vehicleIndex], split1);
        const impact2 = calculateTradeImpact(vehicles[ranked[1].vehicleIndex], split2);
        
        const splitStrategy = {
            type: 'split',
            allocation: {
                [ranked[0].vehicleIndex]: split1,
                [ranked[1].vehicleIndex]: split2
            },
            totalSavings: impact1.totalSavings + impact2.totalSavings,
            description: `Apply $${fmt(split1)} to ${ranked[0].vehicleName} and $${fmt(split2)} to ${ranked[1].vehicleName}`
        };
        
        // Strategy 3: Focus on golden rule failures
        const goldenRuleFailures = scenarios.filter(s => s.goldenRuleStatus === 'fail');
        let goldenRuleStrategy = null;
        
        if (goldenRuleFailures.length > 0) {
            // Calculate minimum equity needed to fix golden rule
            const fixStrategies = goldenRuleFailures.map(failure => {
                const vehicle = vehicles[failure.vehicleIndex];
                const currentPayment = failure.basePayment;
                const targetPayment = (failure.msrp * 1.5) / 100;
                const reductionNeeded = currentPayment - targetPayment;
                
                // Estimate equity needed
                const term = vehicle.results.term || 36;
                const moneyFactor = vehicle.results.moneyFactor || 0.00150;
                const residualPct = vehicle.results.residualPct || 50;
                
                const equityNeeded = (reductionNeeded * term) / (1 - (residualPct/100));
                
                return {
                    vehicleIndex: failure.vehicleIndex,
                    vehicleName: failure.vehicleName,
                    equityNeeded: Math.min(equityNeeded, totalTradeEquity),
                    currentPayment: currentPayment,
                    targetPayment: targetPayment
                };
            });
            
            // Sort by equity needed (ascending)
            fixStrategies.sort((a, b) => a.equityNeeded - b.equityNeeded);
            
            // Try to fix as many as possible
            let remainingEquity = totalTradeEquity;
            const allocation = {};
            let fixedCount = 0;
            
            for (const fix of fixStrategies) {
                if (remainingEquity >= fix.equityNeeded) {
                    allocation[fix.vehicleIndex] = fix.equityNeeded;
                    remainingEquity -= fix.equityNeeded;
                    fixedCount++;
                } else if (remainingEquity > 0) {
                    allocation[fix.vehicleIndex] = remainingEquity;
                    remainingEquity = 0;
                }
            }
            
            goldenRuleStrategy = {
                type: 'golden_rule_focus',
                allocation: allocation,
                fixedCount: fixedCount,
                description: `Focus on achieving golden rule - fixes ${fixedCount} vehicle(s)`,
                details: fixStrategies.map(f => ({
                    vehicle: f.vehicleName,
                    needed: f.equityNeeded,
                    allocated: allocation[f.vehicleIndex] || 0
                }))
            };
        }
        
        // Choose best strategy
        const strategies = [allToTop, splitStrategy];
        if (goldenRuleStrategy) {
            strategies.push(goldenRuleStrategy);
        }
        
        // Score each strategy
        const scoredStrategies = strategies.map(strategy => {
            let score = 0;
            
            // Points for total savings
            score += (strategy.totalSavings || 0) / 100;
            
            // Bonus for fixing golden rule
            if (strategy.type === 'golden_rule_focus') {
                score += strategy.fixedCount * 1000;
            }
            
            // Bonus for simplicity
            if (strategy.type === 'single') {
                score += 100;
            }
            
            return { ...strategy, score };
        });
        
        scoredStrategies.sort((a, b) => b.score - a.score);
        
        return {
            recommended: scoredStrategies[0],
            alternatives: scoredStrategies.slice(1),
            allStrategies: scoredStrategies
        };
    }
    
    return {
        recommended: allToTop,
        alternatives: [],
        allStrategies: [allToTop]
    };
}

/**
 * Generate human-readable recommendation
 * @param {object} strategy - Optimal strategy
 * @returns {object} Formatted recommendation
 */
function generateTradeRecommendation(strategy) {
    const recommended = strategy.recommended;
    
    let title, explanation, steps;
    
    if (recommended.type === 'single') {
        title = '🎯 Recommended: Apply All Trade to One Vehicle';
        explanation = `The highest value is achieved by applying your entire trade equity to one vehicle. This provides the maximum payment reduction and simplifies the transaction.`;
        steps = [
            `Apply $${fmt(Object.values(recommended.allocation)[0])} trade equity to Vehicle #${Object.keys(recommended.allocation)[0] - (-1)}`,
            'Complete transaction for this vehicle with reduced cap cost',
            'Lease other vehicle(s) without trade application'
        ];
    } else if (recommended.type === 'split') {
        title = '⚖️ Recommended: Split Trade Equity';
        explanation = `Distributing your trade equity provides balanced savings across multiple vehicles.`;
        steps = Object.entries(recommended.allocation).map(([idx, amount]) => 
            `Apply $${fmt(amount)} to Vehicle #${parseInt(idx) + 1}`
        );
    } else if (recommended.type === 'golden_rule_focus') {
        title = '🏆 Recommended: Focus on Golden Rule';
        explanation = `Prioritize achieving the 1.5% golden rule for maximum value. This strategy fixes ${recommended.fixedCount} vehicle(s) that are currently failing.`;
        steps = recommended.details.map(detail => 
            `${detail.vehicle}: Apply $${fmt(detail.allocated)} (${detail.allocated >= detail.needed ? 'ACHIEVES' : 'IMPROVES'} golden rule)`
        );
    }
    
    return {
        title,
        explanation,
        steps,
        estimatedMonthlySavings: recommended.totalSavings ? recommended.totalSavings / 36 : null,
        alternatives: strategy.alternatives.map(alt => ({
            type: alt.type,
            description: alt.description,
            savings: alt.totalSavings
        }))
    };
}

/**
 * Render trade optimization results
 * @param {object} analysis - Trade optimization analysis
 * @param {HTMLElement} container - Container element
 */
function renderTradeOptimization(analysis, container) {
    if (!analysis.valid) {
        container.innerHTML = `
            <div class="trade-optimization-unavailable">
                <p>${analysis.message}</p>
            </div>
        `;
        return;
    }
    
    const recommendation = analysis.recommendation;
    
    container.innerHTML = `
        <div class="trade-optimization-results">
            <div class="trade-summary">
                <h3>💰 Trade Equity Available</h3>
                <div class="trade-equity-amount">$${fmt(analysis.tradeEquity)}</div>
            </div>
            
            <div class="trade-recommendation">
                <h3>${recommendation.title}</h3>
                <p class="recommendation-explanation">${recommendation.explanation}</p>
                
                <div class="recommendation-steps">
                    <h4>Implementation Steps:</h4>
                    <ol>
                        ${recommendation.steps.map(step => `<li>${step}</li>`).join('')}
                    </ol>
                </div>
                
                ${recommendation.estimatedMonthlySavings ? `
                    <div class="estimated-savings">
                        <strong>Estimated Monthly Savings:</strong>
                        <span class="savings-amount">$${fmt(recommendation.estimatedMonthlySavings)}/month</span>
                    </div>
                ` : ''}
            </div>
            
            ${recommendation.alternatives.length > 0 ? `
                <div class="alternative-strategies">
                    <h4>Alternative Strategies:</h4>
                    ${recommendation.alternatives.map(alt => `
                        <div class="alternative-card">
                            <strong>${alt.type.replace(/_/g, ' ').toUpperCase()}</strong>
                            <p>${alt.description}</p>
                            ${alt.savings ? `<span class="alt-savings">Saves $${fmt(alt.savings)} over term</span>` : ''}
                        </div>
                    `).join('')}
                </div>
            ` : ''}
            
            <div class="vehicle-scenarios">
                <h4>Individual Vehicle Analysis:</h4>
                ${analysis.scenarios.map(scenario => `
                    <div class="scenario-card">
                        <h5>${scenario.vehicleName} (Value Score: ${scenario.valueScore.toFixed(0)}/100)</h5>
                        
                        <div class="scenario-grid">
                            <div class="scenario-option">
                                <strong>Full Trade Applied</strong>
                                <div class="payment-change">
                                    $${fmt(scenario.basePayment)} → $${fmt(scenario.scenarios.full.newMonthlyPayment)}
                                </div>
                                <div class="savings">Save $${fmt(scenario.scenarios.full.paymentReduction)}/month</div>
                                <div class="golden-status ${scenario.scenarios.full.goldenRuleImpact.passed ? 'pass' : 'fail'}">
                                    ${scenario.scenarios.full.goldenRuleImpact.passed ? '✓' : '✗'} Golden Rule
                                </div>
                            </div>
                            
                            <div class="scenario-option">
                                <strong>No Trade Applied</strong>
                                <div class="payment-change">
                                    $${fmt(scenario.basePayment)}
                                </div>
                                <div class="savings">No change</div>
                                <div class="golden-status ${scenario.scenarios.none.goldenRuleImpact.passed ? 'pass' : 'fail'}">
                                    ${scenario.scenarios.none.goldenRuleImpact.passed ? '✓' : '✗'} Golden Rule
                                </div>
                            </div>
                        </div>
                    </div>
                `).join('')}
            </div>
            
            <button class="btn-apply-trade-optimization" onclick="applyTradeOptimization()">
                Apply Recommended Strategy
            </button>
        </div>
    `;
}

/**
 * Apply recommended trade optimization strategy
 */
function applyTradeOptimization() {
    const analysis = analyzeTradeOptimization();
    if (!analysis.valid) {
        showToast('Cannot apply trade optimization', 'error');
        return;
    }
    
    const strategy = analysis.optimalStrategy.recommended;
    const allocation = strategy.allocation;
    
    // Apply trade equity to designated vehicles
    Object.entries(allocation).forEach(([vehicleIndex, amount]) => {
        const idx = parseInt(vehicleIndex);
        const card = document.querySelectorAll('.vehicle-card')[idx];
        
        if (card && vehicles[idx]) {
            // Update down payment with trade equity
            const currentDown = vehicles[idx].downPayment || 0;
            setFieldValue(card, '.downPayment', currentDown + amount);
            
            // Recalculate
            calculateVehicle(idx);
        }
    });
    
    showToast('Trade optimization applied! Vehicles recalculated.', 'success');
}

